import{_ as n,o as e,c as i,a5 as d}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Test — FR 3.6.3 / DA-1236","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-3-add-comments-on-task/test.md","filePath":"feature/content-task-workflow/3-6-3-add-comments-on-task/test.md"}'),r={name:"feature/content-task-workflow/3-6-3-add-comments-on-task/test.md"};function a(o,t,h,c,s,g){return e(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="test-—-fr-3-6-3-da-1236" tabindex="-1">Test — FR 3.6.3 / DA-1236 <a class="header-anchor" href="#test-—-fr-3-6-3-da-1236" aria-label="Permalink to &quot;Test — FR 3.6.3 / DA-1236&quot;">​</a></h1><p>AC theo <a href="./spec.html">spec</a> §3/6/7. Kết quả cập nhật 2026-10-17 bên dưới; kiểm thử cô lập không thay thế kiểm thử S3/inbox/Gateway thật.</p><p>2026-10-17: C06 no longer includes QC. Verify actual Manager membership, Creator, Client including ClientProfile-resolved User IDs; terminal comments and arbitrary Workspace isolation. Build/compile and isolated browser/manual checks only; no test files under src or commits. Private bucket policy must cover task-comment-images/; never store these under public image/ prefix. Idempotent replay returns the original successful result even after upload expiry/attachment binding, but a changed payload conflicts. Same-key concurrent writes retry as duplicate lookup after transaction abort. Empty content stays invalid even with images, per minLength contract.</p><table tabindex="0"><thead><tr><th>ID</th><th>Input/điều kiện</th><th>AC</th><th>Mong đợi</th><th>Loại</th><th>Trạng thái</th></tr></thead><tbody><tr><td>C01</td><td>Manager/Creator/Client có quyền Task gửi text/link</td><td>Bình luận/timeline</td><td>Author snapshot server, thứ tự/cursor đúng</td><td>Happy</td><td>Chưa test</td></tr><tr><td>C02</td><td>COMPLETED/CANCELLED hoặc Campaign completed</td><td>Terminal comment</td><td>Gửi mới được, không đổi state/round/Campaign</td><td>Edge</td><td>Chưa test</td></tr><tr><td>C03</td><td>Client xem/bình luận Task thủ công requiresClientApproval=false hoặc true</td><td>Q13/Edge §7</td><td>Cả hai đều được, nếu còn active cùng WS</td><td>Happy</td><td>Chưa test</td></tr><tr><td>C04</td><td>Client đọc/gửi comment và xem ảnh ATTACHED trên Task cũ thiếu revision/start</td><td>Q13/legacy</td><td>Được theo membership; không tự sửa state/marker; DRAFT người khác vẫn bị chặn</td><td>Edge</td><td>Chưa test</td></tr><tr><td>C05</td><td>Gỡ membership sau từng tham gia</td><td>Edge §7</td><td>Chặn đọc/gửi/ảnh và delivery mới</td><td>Error</td><td>Chưa test</td></tr><tr><td>C06</td><td>Mention assignee/Managers/tác giả/Client, không QC</td><td>Recipients</td><td>Dedup, bỏ tác giả, Client chỉ mentioned</td><td>Happy</td><td>Pass Mongo/outbox; chờ inbox thật</td></tr><tr><td>C07</td><td>Mention wrong WS/inactive/no Task access</td><td>Mention ACL</td><td>Từ chối, không lộ tên/no delivery</td><td>Error</td><td>Chưa test</td></tr><tr><td>C08</td><td>5 JPEG/PNG/WebP mỗi ảnh đúng 5MB</td><td>Ảnh BA</td><td>Nhận, private, bind đúng một comment</td><td>Happy</td><td>Chưa test</td></tr><tr><td>C09</td><td>6 ảnh, &gt;5MB, MIME giả, corrupt, arbitrary URL</td><td>Ảnh thực/ownership</td><td>Field errors, không lưu comment nửa chừng</td><td>Error</td><td>Chưa test</td></tr><tr><td>C10</td><td>Upload người khác/Task khác/ATTACHED hoặc bind đồng thời</td><td>Ownership</td><td>409/400, không gắn lại</td><td>Error</td><td>Chưa test</td></tr><tr><td>C11</td><td>DRAFT cleanup đua bind; S3 delete lỗi</td><td>Ảnh không mất</td><td>Không xóa ATTACHED, retry giữ metadata tới khi xóa xong</td><td>Edge</td><td>Chưa test</td></tr><tr><td>C12</td><td>Cùng clientRequestId cùng/khác payload</td><td>Retry</td><td>Một comment; khác payload conflict</td><td>Edge</td><td>Chưa test</td></tr><tr><td>C13</td><td>Comment cùng timestamp và phân trang trong lúc có comment mới</td><td>Timeline</td><td>Không mất/trùng item qua cursor</td><td>Edge</td><td>Chưa test</td></tr><tr><td>C14</td><td>HTML/script/javascript URL trong text</td><td>Text/link an toàn</td><td>Escape/plain text, không XSS</td><td>Error</td><td>Chưa test</td></tr><tr><td>C15</td><td>Worker crash sau SQL commit; người nhận mất quyền</td><td>Notification</td><td>Một delivery hoặc SUPPRESSED, không lộ nội dung</td><td>Edge</td><td>Chưa test</td></tr><tr><td>C16</td><td>vi/en/light/dark/mobile/keyboard mention; upload lỗi</td><td>i18n/theme</td><td>Giữ draft/focus, không mất text/ảnh hợp lệ</td><td>Happy</td><td>Chưa test</td></tr><tr><td>C17</td><td>Mongo transaction abort giữa comment/bind/outbox</td><td>Tạo bình luận</td><td>Không comment/notification/binding nửa chừng</td><td>Error</td><td>Chưa test</td></tr><tr><td>C18</td><td>Client truy cập comment/ảnh/mention-options của Task WS khác</td><td>Workspace isolation</td><td>Từ chối, không lộ dữ liệu WS khác</td><td>Error</td><td>Chưa test</td></tr><tr><td>C19</td><td>Gõ @/@tên đầu dòng/sau khoảng trắng, chọn chuột/↑↓ Enter, nhiều lần cùng User</td><td>Nhập trực tiếp</td><td>Thay đúng token, giữ text phía sau/caret, dedup User IDs; không gửi khi chọn tên</td><td>UX</td><td>Chưa test</td></tr><tr><td>C20</td><td>Email, selection khác rỗng, Escape, IME tiếng Việt, tên dài sát 10.000 ký tự</td><td>Không chọn nhầm</td><td>Không popup email, không gửi/chọn trong composition, không cắt mất text khi quá giới hạn, Escape không đóng Task</td><td>Edge</td><td>Chưa test</td></tr><tr><td>C21</td><td>Tìm thành viên chậm/lỗi/không kết quả/phân trang; vi/en/light/dark/375/768/1440</td><td>Feedback/a11y</td><td>Không hiện kết quả cũ để chọn nhầm; retry/load-more; focus giữ ở textarea, danh sách không tràn</td><td>UX</td><td>Chưa test</td></tr><tr><td>C22</td><td>Gõ @ giữa câu/dòng wrap, scroll popup gần mép</td><td>Popup theo caret</td><td>Dropdown nổi tại @, không đẩy layout, flip/clamp trong viewport, không đóng Task khi chọn</td><td>UX</td><td>Chưa test</td></tr><tr><td>C23</td><td>Chọn/xóa/cắt/Undo mention, trùng User, toolbar</td><td>Nhãn inline</td><td>Highlight ngay trong text; User IDs dedup từ nhãn còn lại, xóa nhãn cuối bỏ người nhận; undo khôi phục</td><td>Happy</td><td>Chưa test</td></tr><tr><td>C24</td><td>Paste HTML giả mention/script, &gt;10.000 ký tự, emoji/IME, lỗi gửi rồi retry</td><td>An toàn/giữ draft</td><td>Chỉ plain text; không nhận ID giả, không vượt giới hạn; retry giữ nhãn và request key, gửi xong reset</td><td>Edge</td><td>Chưa test</td></tr></tbody></table><h2 id="bang-chung-kiem-tra-ngay-2026-10-17" tabindex="-1">Bằng chứng kiểm tra ngày 2026-10-17 <a class="header-anchor" href="#bang-chung-kiem-tra-ngay-2026-10-17" aria-label="Permalink to &quot;Bằng chứng kiểm tra ngày 2026-10-17&quot;">​</a></h2><p>Không tạo/commit file test trong src. Helper tạm và ảnh kiểm tra chỉ ở target/ hoặc output/playwright/ đã ignore.</p><ul><li>Backend: 46 test hiện có của TaskWorkflowService/TaskWorkflowMembers/TaskWorkflowController/TaskNotificationWorker pass sau clean build.</li><li>Mongo 7 replica set <strong>container riêng, không gắn volume dữ liệu dự án, localhost:27031</strong>, init từ file hiện tại; 38 assertions pass. Container và dữ liệu kiểm thử tạm đã được dọn sau test. PostgreSQL repositories, inbox và object storage được mock, không dùng Atlas/demo.</li><li>C01/02/04: pass scoped service, author snapshot, ClientProfile → User ID, đọc/gửi trên FINISHED/CANCELLED thiếu workflow markers; không thay Task status/approvalRound/markers.</li><li>C03: xác minh Client được xem terminal Task requiresClientApproval=false; cần test bổ sung manual Task/cờ true qua UI thật.</li><li>C05/07/18: pass ngoại Workspace, mention lạ, Client bị gỡ membership không được đọc/xem ảnh; worker SUPPRESSED với Client đã mất quyền. Chưa stress-test race removal đồng thời xuyên PostgreSQL/Mongo.</li><li>C08/09: PNG/JPEG/WebP thật decode thành công; PNG đúng 5 MiB được nhận; MIME giả bị từ chối. Browser chặn ảnh 5 MiB + 1. Chưa chạy toàn bộ tổ hợp 5/6 ảnh và malformed image qua multipart thật.</li><li>C10/11: chủ upload preview được DRAFT, người khác bị chặn; ATTACHED có quyền Task đọc được; không bind ảnh người khác; cleanup xóa DRAFT hết hạn và giữ ATTACHED. Chưa fault-injection lỗi S3 delete/race cleanup với bind thật.</li><li>C12/13/17: hai luồng cùng clientRequestId chỉ một comment; replay sau gắn ảnh trả comment cũ, đổi payload conflict; cursor cùng timestamp không mất/trùng; lỗi bind thứ hai rollback cả binding thứ nhất, không comment/outbox nửa chừng.</li><li>C14/16: browser thật với API mock: script hiển thị plain text; mention, lỗi mất response giữ draft, retry cùng requestId không tạo trùng, ảnh/upload/preview hoạt động. Đã xem screenshot light tại 375/768/1440 và dark tại 1440; không tràn vùng comment. Chưa test locale en và mọi phím trên mọi browser.</li><li>C15: worker comment gửi tới mock inbox trên terminal Task và suppress Client bị gỡ. SQL ON CONFLICT reuse adapter hiện có; chưa giả lập crash sau SQL commit trên PostgreSQL thật.</li><li>ESLint phần Web mới pass. TypeScript toàn repo chưa pass do lỗi sẵn ở Content Writing/editor/Workspace dashboard/AppRoutes; không sửa phần thành viên khác. Không có lỗi TypeScript trỏ tới file comment mới tại lần kiểm tra này.</li></ul><p>Các dòng “Chưa test” trong bảng là case đầy đủ chưa được xác minh end-to-end; các kiểm tra con đã qua được ghi rõ ở trên, không tự đánh pass toàn bộ từ mock.</p><h3 id="bo-sung-truc-tiep-trong-o-nhap" tabindex="-1">Bổ sung @ trực tiếp trong ô nhập <a class="header-anchor" href="#bo-sung-truc-tiep-trong-o-nhap" aria-label="Permalink to &quot;Bổ sung @ trực tiếp trong ô nhập&quot;">​</a></h3><ul><li>Parser/replacement: 17 assertions pass bằng helper local ngoài src: đầu dòng/whitespace, Unicode dấu tổ hợp, email/URL, selection không rỗng, caret giữa token, giữ suffix/dấu câu, không cắt text vượt 10.000 ký tự.</li><li>Browser API-mock: C19 pass keyboard ↑↓ Enter, click chọn, giữ focus/caret và văn bản phía sau, dedup User IDs trong payload; chọn tên không POST, Ctrl+Enter khi đã chọn mới gửi.</li><li>C20: pass email không mở danh sách, Escape chỉ đóng gợi ý (chặn trước handler capture của Task dialog), composition Enter/Ctrl+Enter không gửi nhầm; giới hạn độ dài kiểm helper, chưa thử mọi bộ gõ thực tế.</li><li>C21: pass empty/error/retry, layout light tại 375/768/1440, dark 1440 và đổi vi/en. Đã xem ảnh chụp; test dùng API mock, chưa stress-test phân trang/chậm mạng và screen reader thực tế. Không có lỗi lint phần mới; typecheck vẫn chỉ báo các lỗi ngoài scope đã liệt kê.</li></ul><h3 id="dropdown-tai-caret-va-mention-inline-ux-thay-cho-textarea" tabindex="-1">Dropdown tại caret và mention inline (UX thay cho textarea) <a class="header-anchor" href="#dropdown-tai-caret-va-mention-inline-ux-thay-cho-textarea" aria-label="Permalink to &quot;Dropdown tại caret và mention inline (UX thay cho textarea)&quot;">​</a></h3><ul><li>C22 browser API-mock pass: đo popup.x so với Range của ký tự @ trên desktop (sai số ≤3 px), ô nhập không đổi chiều cao khi mở popup; popup không vượt viewport 375/768/1440. Đã xem screenshot desktop/mobile và nhãn dark/en. Radix Popover virtual anchor theo vị trí @, không sửa primitive chung.</li><li>C23 pass: chọn chuột/↑↓ Enter chèn node có nền nổi bật; xóa nguyên node bằng Backspace và Undo khôi phục; Ctrl+X cắt nhãn và Ctrl+Z khôi phục; nhắc cùng User nhiều lần chỉ gửi một ID; xóa nhãn cuối không còn ID trong payload gửi tiếp. Toolbar Nhắc tên vẫn chèn node và giữ được khi upload ảnh. Chưa kiểm mọi tổ hợp trên các browser.</li><li>C24 pass: retry sau mất response giữ node và cùng clientRequestId; gửi xong editor rỗng; paste HTML/script/mention giả chỉ thành plain text và không có User ID; không vượt 10.000 ký tự; composition Enter không chọn/gửi. Header/lịch sử comment vẫn dùng dữ liệu plain text, không suy đoán highlight từ tên người trong dữ liệu cũ.</li><li>ESLint các file mới pass; typecheck toàn repo vẫn bị chặn bởi các lỗi Content Writing/editor/dashboard/AppRoutes ngoài scope đã ghi. Không sửa package.json/lockfile hoặc thêm test trong src. Không có thay đổi Backend/API/DB cho phần UX này.</li></ul>',12)])])}const m=n(r,[["render",a]]);export{p as __pageData,m as default};
